<template>
  <section class="panel fund-operations-panel">
    <header class="fund-head">
      <div><h2>{{ $t('legacy.t_518251a4b932') }}</h2><p>{{ $t('legacy.t_2507fe52485c') }}</p></div>
      <div><button type="button" @click="openTransfer">{{ $t('legacy.t_47bddac69cda') }}</button><button type="button" class="primary" @click="openBatch">{{ $t('legacy.t_d57cc7de03e1') }}</button></div>
    </header>
    <nav class="fund-tabs" :aria-label="$t('legacy.t_fe8d0cc726a0')">
      <button v-for="item in tabs" :key="item.key" type="button" :class="{active:tab===item.key}" @click="tab=item.key">{{ $lt(item.label) }} <b>{{ item.count }}</b></button>
    </nav>

    <p v-if="error" class="fund-error" role="alert">{{ $lt(error) }} <button type="button" @click="load">{{ $t('legacy.t_e2d53a6d3a6a') }}</button></p>
    <div v-else-if="loading" class="fund-empty">{{ $t('legacy.t_e60c30cc3618') }}</div>

    <div v-else-if="tab==='transfers'" class="fund-table-wrap">
      <table><thead><tr><th>{{ $t('legacy.t_cbbdcc073069') }}</th><th>{{ $t('legacy.t_a39a3f21f732') }}</th><th>{{ $t('legacy.t_817821cfc80d') }}</th><th>{{ $t('legacy.t_34943c40c9af') }}</th><th>{{ $t('legacy.t_dd17b4ae5063') }}</th><th>{{ $t('legacy.t_62e951a692ff') }}</th><th>{{ $t('legacy.t_f3ea6d345e2a') }}</th></tr></thead><tbody>
        <tr v-for="item in data.internalTransfers" :key="item.id"><td><strong>{{ item.transferNo }}</strong><small>{{ item.reason }}</small></td><td>{{ item.ownerName }}</td><td>{{ item.sourceProperty }}<br>→ {{ item.targetProperty }}</td><td>{{ $t('legacy.t_5e7b60c626a4') }} {{ money(item.amount) }}</td><td>{{ formatDate(item.requestedDate) }}</td><td><span class="fund-status" :class="item.status">{{ $lt(statusLabel(item.status)) }}</span></td><td class="fund-actions"><button v-if="item.status==='pending'" type="button" @click="actTransfer(item,'approve')">{{ $t('legacy.t_5ce60cb75d20') }}</button><button v-if="item.status==='pending'" type="button" class="danger" @click="actTransfer(item,'reject')">{{ $t('legacy.t_21ec781468c9') }}</button><button v-if="item.status==='approved'" type="button" class="danger" @click="actTransfer(item,'reverse')">{{ $t('legacy.t_47524db6a426') }}</button></td></tr>
        <tr v-if="!data.internalTransfers.length"><td colspan="7" class="fund-empty">{{ $t('legacy.t_7771056327f4') }}</td></tr>
      </tbody></table>
    </div>

    <div v-else-if="tab==='settings'" class="fund-table-wrap">
      <table><thead><tr><th>{{ $t('legacy.t_0c949feb64cf') }}</th><th>{{ $t('legacy.t_8a12b12125c2') }}</th><th>{{ $t('legacy.t_6491697d4588') }}</th><th>{{ $t('legacy.t_0ab18fffcd42') }}</th><th>{{ $t('legacy.t_01977fab253e') }}</th><th>{{ $t('legacy.t_62e951a692ff') }}</th><th>{{ $t('legacy.t_2a04e590b25f') }}</th><th>{{ $t('legacy.t_f3ea6d345e2a') }}</th></tr></thead><tbody>
        <tr v-for="item in data.remittanceSettings" :key="item.id"><td><strong>{{ item.ownerName }}</strong><small>{{ item.propertyName }}</small></td><td>{{ $lt(cycleLabel(item.cycle)) }}</td><td>{{ formatDate(item.nextRemittanceDate) }}</td><td>{{ $t('legacy.t_5e7b60c626a4') }} {{ money(item.retainedAmount) }}</td><td>{{ $t('legacy.t_5e7b60c626a4') }} {{ money(item.taxRetainedAmount) }}</td><td><span class="fund-status" :class="item.holdEnabled?'rejected':item.enabled?'approved':'cancelled'">{{ item.holdEnabled ? $t('ui.suspendedReason', { reason: item.holdReason }) : item.enabled ? $t('legacy.t_d4e9ca3dd494') : $t('legacy.t_d989e55188c9') }}</span></td><td>{{ item.bankName || '—' }}<small>{{ item.bankAccountNo || '' }}</small></td><td><button type="button" @click="openSetting(item.reserveAccountId)">{{ $t('legacy.t_a7f814c0a40d') }}</button></td></tr>
        <tr v-if="!data.remittanceSettings.length"><td colspan="8" class="fund-empty">{{ $t('legacy.t_a52840457925') }}</td></tr>
      </tbody></table>
    </div>

    <div v-else class="batch-list">
      <article v-for="batch in data.remittanceBatches" :key="batch.id">
        <header><div><strong>{{ batch.batchNo }}</strong><small>{{ formatDate(batch.scheduledDate) }} · {{ batch.itemCount }} {{ $t('legacy.t_de1969c7aab8') }} {{ money(batch.totalAmount) }}</small></div><span class="fund-status" :class="batch.status">{{ $lt(statusLabel(batch.status)) }}</span></header>
        <div class="batch-items"><span v-for="item in batch.items" :key="item.id"><b>{{ item.ownerName }} · {{ item.propertyName }}</b><small>{{ $t('legacy.t_5e7b60c626a4') }} {{ money(item.amount) }} · {{ $lt(paymentLabel(item)) }}</small></span></div>
        <footer><p>{{ batch.note || $t('legacy.t_7734db66e2a3') }}</p><div class="fund-actions"><button v-if="batch.status==='draft'" type="button" @click="actBatch(batch,'submit')">{{ $t('legacy.t_3468c812b7b8') }}</button><button v-if="batch.status==='draft'" type="button" class="danger" @click="actBatch(batch,'reject')">{{ $t('legacy.t_3d8bac095080') }}</button></div></footer>
      </article>
      <div v-if="!data.remittanceBatches.length" class="fund-empty">{{ $t('legacy.t_fc736d32fe6a') }}</div>
    </div>

    <dialog ref="transferDialog" class="fund-dialog"><form @submit.prevent="saveTransfer"><header><h3>{{ $t('legacy.t_47bddac69cda') }}</h3><button type="button" @click="$refs.transferDialog.close()">×</button></header><div class="fund-form">
      <label>{{ $t('legacy.t_c6a74857d5db') }}<select v-model.number="transfer.sourceReserveAccountId" required><option disabled :value="null">{{ $t('legacy.t_382f4b5559b3') }}</option><option v-for="item in data.reserveAccounts" :key="item.id" :value="item.id">{{ $lt(accountLabel(item)) }}</option></select></label>
      <label>{{ $t('legacy.t_a0a4428dee7a') }}<select v-model.number="transfer.targetReserveAccountId" required><option disabled :value="null">{{ $t('legacy.t_382f4b5559b3') }}</option><option v-for="item in transferTargets" :key="item.id" :value="item.id">{{ $lt(accountLabel(item)) }}</option></select><small>{{ $t('legacy.t_deecb7edfa17') }}</small></label>
      <label>{{ $t('legacy.t_0a151a5f44ba') }}<input v-model="transfer.amount" type="number" min="0.01" step="0.01" required></label><label>{{ $t('legacy.t_2c346345746e') }}<input v-model="transfer.requestedDate" type="date" required></label>
      <label class="wide">{{ $t('legacy.t_913cf3b6f3d1') }}<textarea v-model.trim="transfer.reason" maxlength="500" rows="3" required></textarea></label><p v-if="formError" class="fund-error wide">{{ $lt(formError) }}</p>
    </div><menu><button type="button" @click="$refs.transferDialog.close()">{{ $t('legacy.t_4d0b4688c787') }}</button><button class="primary" :disabled="saving">{{ saving?$t('legacy.t_6644f06197a4'):$t('legacy.t_554da87f544c') }}</button></menu></form></dialog>

    <dialog ref="settingDialog" class="fund-dialog"><form @submit.prevent="saveSetting"><header><h3>{{ $t('legacy.t_fd409d55d38e') }}</h3><button type="button" @click="$refs.settingDialog.close()">×</button></header><div class="fund-form">
      <label class="wide">{{ $t('legacy.t_3efc1beb7b20') }}<select v-model.number="setting.accountId" required @change="fillSetting"><option v-for="item in data.reserveAccounts" :key="item.id" :value="item.id">{{ $lt(accountLabel(item)) }}</option></select></label>
      <label>{{ $t('legacy.t_42d7cfd4f4b8') }}<select v-model="setting.cycle"><option value="monthly">{{ $t('legacy.t_24aedc360803') }}</option><option value="quarterly">{{ $t('legacy.t_fe965ba52d95') }}</option><option value="semiannual">{{ $t('legacy.t_9a3b49115b8a') }}</option><option value="manual">{{ $t('legacy.t_2a4a4de8068b') }}</option></select></label><label>{{ $t('legacy.t_71e82bfa1445') }}<input v-model="setting.nextRemittanceDate" type="date" :required="setting.enabled&&setting.cycle!=='manual'"></label>
      <label>{{ $t('legacy.t_6b287bb41cc0') }}<input v-model="setting.retainedAmount" type="number" min="0" step="0.01" required></label><label>{{ $t('legacy.t_2a704f1b6139') }}<input v-model="setting.taxRetainedAmount" type="number" min="0" step="0.01" required></label>
      <label class="wide">{{ $t('legacy.t_4d3986e0952b') }}<select v-model.number="setting.defaultBankAccountId" :required="setting.enabled&&setting.cycle!=='manual'"><option :value="null">{{ $t('legacy.t_55a04b58cd2c') }}</option><option v-if="selectedAccount?.defaultBankAccountId" :value="selectedAccount.defaultBankAccountId">{{ selectedAccount.defaultBankName }} · {{ selectedAccount.defaultBankAccountNo }}</option></select></label>
      <label class="check"><input v-model="setting.enabled" type="checkbox">{{ $t('legacy.t_7f921809c691') }}</label><label class="check"><input v-model="setting.holdEnabled" type="checkbox">{{ $t('legacy.t_713907b17855') }}</label>
      <label v-if="setting.holdEnabled" class="wide">{{ $t('legacy.t_14b2e2a1219f') }}<textarea v-model.trim="setting.holdReason" maxlength="500" rows="2" required></textarea></label><label v-if="setting.holdEnabled">{{ $t('legacy.t_a18cec0bd842') }}<input v-model="setting.holdUntil" type="date"></label><p v-if="formError" class="fund-error wide">{{ $lt(formError) }}</p>
    </div><menu><button type="button" @click="$refs.settingDialog.close()">{{ $t('legacy.t_4d0b4688c787') }}</button><button class="primary" :disabled="saving">{{ saving?$t('legacy.t_6644f06197a4'):$t('legacy.t_4317caf2463a') }}</button></menu></form></dialog>

    <dialog ref="batchDialog" class="fund-dialog"><form @submit.prevent="generateBatch"><header><h3>{{ $t('legacy.t_d57cc7de03e1') }}</h3><button type="button" @click="$refs.batchDialog.close()">×</button></header><div class="fund-form"><label>{{ $t('legacy.t_9e8b2bdbb685') }}<input v-model="batch.scheduledDate" type="date" required></label><label class="wide">{{ $t('legacy.t_3bd7abaa8991') }}<textarea v-model.trim="batch.note" maxlength="500" rows="3"></textarea></label><p class="fund-hint wide">{{ $t('legacy.t_792cce46d354') }}</p><p v-if="formError" class="fund-error wide">{{ $lt(formError) }}</p></div><menu><button type="button" @click="$refs.batchDialog.close()">{{ $t('legacy.t_4d0b4688c787') }}</button><button class="primary" :disabled="saving">{{ saving?$t('legacy.t_3a98deb05d52'):$t('legacy.t_91a575bff122') }}</button></menu></form></dialog>
  </section>
</template>

<script>
import { formatDate, formatDateTime, formatMonth } from '../utils/dateFormat';
import { createAdminInternalTransfer, fetchAdminFundOperations, generateAdminRemittanceBatch, reviewAdminInternalTransfer, reviewAdminRemittanceBatch, saveAdminRemittanceSetting } from '../services/propertyApi';
const today=()=>{const d=new Date();d.setMinutes(d.getMinutes()-d.getTimezoneOffset());return d.toISOString().slice(0,10)};
const emptyData=()=>({reserveAccounts:[],internalTransfers:[],remittanceSettings:[],remittanceBatches:[]});
const emptySetting=()=>({accountId:null,cycle:'quarterly',nextRemittanceDate:'',enabled:true,holdEnabled:false,holdReason:'',holdUntil:'',retainedAmount:'0.00',taxRetainedAmount:'0.00',defaultBankAccountId:null});
export default{
  inject:['page'],
  data(){return{data:emptyData(),tab:'transfers',loading:false,saving:false,error:'',formError:'',transfer:{sourceReserveAccountId:null,targetReserveAccountId:null,amount:'',requestedDate:today(),reason:''},setting:emptySetting(),batch:{scheduledDate:today(),note:''}}},
  computed:{tabs(){return[{key:'transfers',label:'内部调拨',count:this.data.internalTransfers.length},{key:'settings',label:'汇款计划',count:this.data.remittanceSettings.length},{key:'batches',label:'汇款批次',count:this.data.remittanceBatches.length}]},sourceAccount(){return this.data.reserveAccounts.find(x=>x.id===this.transfer.sourceReserveAccountId)},transferTargets(){return this.sourceAccount?this.data.reserveAccounts.filter(x=>x.ownerId===this.sourceAccount.ownerId&&x.id!==this.sourceAccount.id):[]},selectedAccount(){return this.data.reserveAccounts.find(x=>x.id===this.setting.accountId)}},
  mounted(){this.load()},
  methods: {
    formatDate, formatDateTime, formatMonth,
    async load(){this.loading=true;this.error='';try{this.data=await fetchAdminFundOperations()}catch(e){this.error=e.message||'资金操作加载失败'}finally{this.loading=false}},
    apply(result,message){this.data=result;this.page?.showToast?.(message)},
    openTransfer(){this.transfer={sourceReserveAccountId:null,targetReserveAccountId:null,amount:'',requestedDate:today(),reason:''};this.formError='';this.$refs.transferDialog.showModal()},
    async saveTransfer(){this.saving=true;this.formError='';try{const result=await createAdminInternalTransfer({...this.transfer,amount:Number(this.transfer.amount).toFixed(2)});this.apply(result,'内部调拨申请已建立');this.$refs.transferDialog.close()}catch(e){this.formError=e.message||'内部调拨建立失败'}finally{this.saving=false}},
    async actTransfer(item,action){const labels={approve:'审批通过',reject:'驳回',reverse:'冲正'};const note=window.prompt(this.$ltf`请填写${labels[action]}备注（可留空）`,'');if(note===null)return;try{this.apply(await reviewAdminInternalTransfer(item.id,action,note),this.$ltf`内部调拨已${labels[action]}`)}catch(e){this.page?.showToast?.(e.message||'操作失败')}},
    openSetting(accountId=null){this.setting=emptySetting();this.setting.accountId=accountId||this.data.reserveAccounts[0]?.id||null;this.fillSetting();this.formError='';this.$refs.settingDialog.showModal()},
    fillSetting(){const current=this.data.remittanceSettings.find(x=>x.reserveAccountId===this.setting.accountId),account=this.selectedAccount;this.setting=current?{accountId:current.reserveAccountId,cycle:current.cycle,nextRemittanceDate:current.nextRemittanceDate||'',enabled:current.enabled,holdEnabled:current.holdEnabled,holdReason:current.holdReason||'',holdUntil:current.holdUntil||'',retainedAmount:String(current.retainedAmount||0),taxRetainedAmount:String(current.taxRetainedAmount||0),defaultBankAccountId:current.defaultBankAccountId}:{...emptySetting(),accountId:this.setting.accountId,defaultBankAccountId:account?.defaultBankAccountId||null}},
    async saveSetting(){this.saving=true;this.formError='';try{const p={...this.setting,nextRemittanceDate:this.setting.nextRemittanceDate||null,holdReason:this.setting.holdReason||null,holdUntil:this.setting.holdUntil||null,retainedAmount:Number(this.setting.retainedAmount||0).toFixed(2),taxRetainedAmount:Number(this.setting.taxRetainedAmount||0).toFixed(2)};delete p.accountId;this.apply(await saveAdminRemittanceSetting(this.setting.accountId,p),'汇款计划已保存');this.$refs.settingDialog.close()}catch(e){this.formError=e.message||'汇款计划保存失败'}finally{this.saving=false}},
    openBatch(){this.batch={scheduledDate:today(),note:''};this.formError='';this.$refs.batchDialog.showModal()},async generateBatch(){this.saving=true;this.formError='';try{this.apply(await generateAdminRemittanceBatch({...this.batch,note:this.batch.note||null}),'到期汇款批次已生成');this.tab='batches';this.$refs.batchDialog.close()}catch(e){this.formError=e.message||'汇款批次生成失败'}finally{this.saving=false}},
    async actBatch(batch,action){const label=action==='submit'?'提交财务确认':'驳回';const note=window.prompt(this.$ltf`请填写${label}备注（可留空）`,'');if(note===null)return;try{this.apply(await reviewAdminRemittanceBatch(batch.id,action,note),this.$ltf`汇款批次已${label}`)}catch(e){this.page?.showToast?.(e.message||'操作失败')}},
    accountLabel(x){return`${x.ownerName} · ${x.projectName}/${x.unitNo} · RM ${this.money(x.currentBalance)}`},money(v){return Number(v||0).toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2})},cycleLabel(v){return({monthly:'每月',quarterly:'每季度',semiannual:'每半年',manual:'手动'})[v]||v},statusLabel(v){return({pending:'待审批',approved:'已审批',rejected:'已驳回',reversed:'已冲正',draft:'草稿',submitted:'待财务确认',completed:'已完成',cancelled:'已取消'})[v]||v},paymentLabel(i){return i.confirmationStatus==='confirmed'?'财务已确认':i.confirmationStatus==='rejected'?'财务已驳回':i.financeRecordId?'待财务确认':'未提交'}
  }
};
</script>

<style scoped>
.fund-operations-panel{grid-column:1/-1;min-width:0;padding:18px}.fund-head,.fund-head>div:last-child,.fund-tabs,.fund-actions{display:flex;align-items:center;gap:9px}.fund-head{justify-content:space-between}.fund-head h2{margin:0 0 4px;color:#123b59}.fund-head p,.fund-hint{margin:0;color:#718096;font-size:12px}.fund-head button,.fund-actions button,.fund-tabs button,.fund-table-wrap button{border:1px solid #cbd9e5;border-radius:7px;background:#fff;padding:8px 11px;color:#155b72}.fund-head .primary,.fund-dialog .primary{border-color:#0b8f96;background:#0b8f96;color:#fff}.fund-tabs{margin:16px 0 12px;border-bottom:1px solid #dfe8ee}.fund-tabs button{border:0;border-radius:7px 7px 0 0;background:transparent;color:#64748b}.fund-tabs button.active{background:#e8f6f6;color:#08767d;font-weight:800}.fund-tabs b{display:inline-grid;place-items:center;min-width:20px;height:20px;border-radius:999px;background:#edf1f4;font-size:11px}.fund-table-wrap{overflow:auto;border:1px solid #dce6ec;border-radius:9px}.fund-table-wrap table{width:100%;min-width:980px;border-collapse:collapse}.fund-table-wrap th{padding:9px 10px;background:#f3f7f8;color:#5d7485;font-size:11px;text-align:left}.fund-table-wrap td{padding:10px;border-top:1px solid #e5ecef;color:#28465a;font-size:12px}.fund-table-wrap strong,.fund-table-wrap small{display:block}.fund-table-wrap small{margin-top:3px;color:#8293a1}.fund-status{display:inline-flex;max-width:220px;padding:4px 8px;border-radius:999px;background:#eef2f4;color:#60717e;font-size:11px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.fund-status.approved,.fund-status.completed{background:#e6f7ed;color:#168047}.fund-status.pending,.fund-status.draft,.fund-status.submitted{background:#fff4d9;color:#966300}.fund-status.rejected,.fund-status.reversed{background:#fff0f0;color:#c43a3a}.fund-actions .danger{border-color:#edcaca;color:#c43a3a}.fund-empty{padding:28px;text-align:center;color:#788b99}.fund-error{padding:10px 12px;border-radius:7px;background:#fff0f0;color:#c43a3a}.batch-list{display:grid;gap:10px}.batch-list article{border:1px solid #dce6ec;border-radius:9px;overflow:hidden}.batch-list article>header,.batch-list article>footer{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:11px 13px;background:#f8fbfc}.batch-list article>header div,.batch-list article>header small{display:grid;gap:3px}.batch-list small{color:#718096}.batch-items{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px;padding:12px}.batch-items span{display:grid;gap:4px;padding:9px;border-radius:7px;background:#f5f8fa;font-size:11px}.batch-list footer p{margin:0;color:#657b8a;font-size:11px}.fund-dialog{width:min(720px,calc(100vw - 32px));padding:0;border:0;border-radius:12px;box-shadow:0 22px 70px #10233b42}.fund-dialog::backdrop{background:#0a172a80}.fund-dialog header{display:flex;align-items:center;justify-content:space-between;padding:17px 20px;border-bottom:1px solid #e0e7ed}.fund-dialog h3{margin:0}.fund-dialog header button{border:0;background:none;font-size:25px}.fund-form{display:grid;grid-template-columns:1fr 1fr;gap:13px;padding:18px 20px}.fund-form label{display:grid;gap:6px;color:#365469;font-size:12px;font-weight:700}.fund-form input,.fund-form select,.fund-form textarea{box-sizing:border-box;width:100%;border:1px solid #cad8e2;border-radius:7px;padding:9px;background:#fff;color:#18384d}.fund-form textarea{resize:vertical}.fund-form .wide{grid-column:1/-1}.fund-form .check{display:flex;align-items:center}.fund-form .check input{width:16px}.fund-dialog menu{display:flex;justify-content:flex-end;gap:8px;margin:0;padding:12px 20px;background:#f7f9fa}.fund-dialog menu button{border:1px solid #cbd8e2;border-radius:7px;background:#fff;padding:9px 15px}.fund-dialog menu button:disabled{opacity:.55}@media(max-width:800px){.fund-head{align-items:flex-start;flex-direction:column}.batch-items,.fund-form{grid-template-columns:1fr}.fund-form .wide{grid-column:auto}}
</style>
